<?php
require_once __DIR__ . '/../_common.php';
function userGenderAuth($v):array{$x=strtolower(trim((string)$v));if(in_array($x,['l','laki-laki','laki laki'],true))return['L','Laki-laki'];if(in_array($x,['p','perempuan'],true))return['P','Perempuan'];throw new InvalidArgumentException('gender harus L atau P.');}
try{$m=api_allow_methods(['GET','POST']);if($m==='GET'){if(empty($_SESSION['id_akun'])||($_SESSION['role']??'')!=='user')api_reply(401,false,'Belum login sebagai user.',null);api_reply(200,true,'Sesi user aktif.',['id_akun'=>(int)$_SESSION['id_akun'],'id_user'=>(int)($_SESSION['id_user']??0),'role'=>'user','nama'=>$_SESSION['nama']??null]);}$b=api_body();$action=$b['action']??'login';if($action==='logout'){if(($_SESSION['role']??'')!=='user')api_reply(401,false,'Belum login.',null);$_SESSION=[];session_destroy();api_reply(200,true,'Logout berhasil.',null);}
if($action==='register'){$name=api_string($b['nama_pengguna']??($b['nama']??null),'nama_pengguna',100);$email=api_string($b['email']??null,'email',100);$phone=api_string($b['nomor_telepon']??($b['no_telp']??null),'nomor_telepon',20);$address=api_string($b['alamat']??null,'alamat',10000);$birth=api_string($b['tanggal_lahir']??null,'tanggal_lahir',10);[$genderAccount,$genderUser]=userGenderAuth($b['gender']??null);$password=api_string($b['password']??null,'password',255);$confirm=api_string($b['konfirmasi_password']??$password,'konfirmasi_password',255);if($password!==$confirm)throw new InvalidArgumentException('Konfirmasi kata sandi tidak sama.');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Format email tidak valid.');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$birth))throw new InvalidArgumentException('tanggal_lahir harus YYYY-MM-DD.');$conn->begin_transaction();try{$s=$conn->prepare('SELECT id_user FROM users WHERE email=? LIMIT 1');$s->bind_param('s',$email);$s->execute();if(api_one($s))throw new DomainException('Email sudah terdaftar.');$s->close();$hash=password_hash($password,PASSWORD_DEFAULT);$end='minggu';$s=$conn->prepare("INSERT INTO akun(nama,email,password,role,tanggal_lahir,no_telp,gender,alamat,hari_kerja_selesai) VALUES(?,?,?,'user',?,?,?,?,?)");$s->bind_param('ssssssss',$name,$email,$hash,$birth,$phone,$genderAccount,$address,$end);$s->execute();$idA=(int)$conn->insert_id;$s->close();$s=$conn->prepare('INSERT INTO users(nama,no_telp,email,alamat,tanggal_lahir,password,gender,id_akun) VALUES(?,?,?,?,?,?,?,?)');$s->bind_param('sssssssi',$name,$phone,$email,$address,$birth,$hash,$genderUser,$idA);$s->execute();$idU=(int)$conn->insert_id;$s->close();$conn->commit();}catch(Throwable $e){$conn->rollback();throw $e;}api_reply(201,true,'Pendaftaran berhasil. Silakan login.',['id_user'=>$idU]);}
$email=api_string($b['email']??null,'email',100);$password=api_string($b['password']??null,'password',255);$s=$conn->prepare("SELECT a.id_akun,a.nama,a.password,a.status_akun,u.id_user FROM akun a JOIN users u ON u.id_akun=a.id_akun WHERE a.email=? AND a.role='user' LIMIT 1");$s->bind_param('s',$email);$s->execute();$row=api_one($s);$s->close();if(!$row||$row['status_akun']!=='aktif'||!password_verify($password,(string)$row['password']))api_reply(401,false,'Email atau kata sandi salah.',null);session_regenerate_id(true);$_SESSION['id_akun']=(int)$row['id_akun'];$_SESSION['id_user']=(int)$row['id_user'];$_SESSION['role']='user';$_SESSION['nama']=$row['nama'];api_reply(200,true,'Login user berhasil.',['id_akun'=>(int)$row['id_akun'],'id_user'=>(int)$row['id_user'],'nama'=>$row['nama'],'role'=>'user']);}catch(Throwable $e){api_db_error($e);}